use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl TokenCursor { pub fn next (& mut self) -> (Token , Spacing) { self . inlined_next () } # [doc = " This always-inlined version should only be used on hot code paths."] # [inline (always)] pub fn inlined_next (& mut self) -> (Token , Spacing) { loop { if let Some (tree) = self . curr . curr () { match tree { & TokenTree :: Token (token , spacing) => { debug_assert ! (! token . kind . is_delim ()) ; let res = (token , spacing) ; self . curr . bump () ; return res ; } & TokenTree :: Delimited (sp , spacing , delim , ref tts) => { let trees = TokenTreeCursor :: new (tts . clone ()) ; self . stack . push (mem :: replace (& mut self . curr , trees)) ; if ! delim . skip () { return (Token :: new (delim . as_open_token_kind () , sp . open) , spacing . open) ; } } } ; } else if let Some (parent) = self . stack . pop () { let Some (& TokenTree :: Delimited (span , spacing , delim , _)) = parent . curr () else { panic ! ("parent should be Delimited") } ; self . curr = parent ; self . curr . bump () ; if ! delim . skip () { return (Token :: new (delim . as_close_token_kind () , span . close) , spacing . close) ; } } else { return (Token :: new (token :: Eof , DUMMY_SP) , Spacing :: Alone) ; } } } }